package main

import "fmt"

func IntersectionSorted(a, b []int) []int {
	var result []int
	i, j := 0, 0

	for i < len(a) && j < len(b) {
		if a[i] < b[j] {
			i++
		} else if a[i] > b[j] {
			j++
		} else {
			// 去重逻辑：如果结果集为空或最后一个元素不等于当前值，则放入
			if len(result) == 0 || result[len(result)-1] != a[i] {
				result = append(result, a[i])
			}
			i++
			j++
		}
	}
	return result
}

func main() {
	a := []int{1, 2, 2, 4, 5}
	b := []int{2, 2, 4, 6, 8}

	fmt.Println(IntersectionSorted(a, b)) // 输出: [2 4]
}


